let router = @contract(uniswap/v2router)
and weth = @token(weth/weth)
and usdc = @token(circle/usdc)
and steth = @contract(lido/steth)
and amountOutMin = $floor($arg0 * $price(usdc, 18, 86400) * 99 / ($price(weth, 6, 86400) * 100))
in {
  $require(usdc.approve(router, $arg0)),
  let before = $balance($this),
  $require(router.swapExactTokensForETH(
    $arg0,
    amountOutMin,
    [usdc, weth],
    $this,
    $deadline(),
  )),
  $require(usdc.approve(router, 0)),
  let after = $balance($this),
  $require(after >= before),
  $require(steth.submit{value: after - before}(0)),
}

let manager = @contract(eth/uniswap-v3-position-manager)
and token0 = @token(circle/usdc)
and token1 = @token(weth/weth)
and feeTier = 500
and tickLower = $arg0
and tickUpper = $arg1
and amount0Desired = $arg2
and amount1Desired = $arg3
and amount0Min = $arg4
and amount1Min = $arg5
in {
  {
 let root = @contract(eth/uniswap-v3-usdc-weth-500).slot0(),
 let price0 = $price(@token(circle/usdc), 18, 86400),
 let price1 = $price(@token(weth/weth), 18, 86400),
 let squared = $floor(root * root / 79228162514264337593543950336),
 let lowerPrice = $floor(squared * price1 / 79228162514264337593543950336000000000000),
 let upperPrice = $floor((squared + 1) * price1 / 79228162514264337593543950336000000000000),
 let tolerance = $floor(price0 / 100),
 $require(lowerPrice >= price0 - tolerance),
 $require(upperPrice < price0 + tolerance),
 true,
},
  $require(token0.approve(manager, amount0Desired)),
  $require(token1.approve(manager, amount1Desired)),
  $require(manager.mint{value: 0}({token0, token1, feeTier, tickLower, tickUpper, amount0Desired, amount1Desired, amount0Min, amount1Min, $self, $deadline()})),
  $require(token0.approve(manager, 0)),
  $require(token1.approve(manager, 0)),
}

