let pool = @contract(eth/aave-v3)
and asset = @token(weth/weth)
and reserve = @contract(aave/aeth)
in {
  $require($arg0 > 0 && $arg1 > 0),
  $require(pool.borrow(asset, $arg0, 2, 0, $self)),
  $require(asset.balanceOf(reserve) >= $arg1),
}
